import {managers,names,fmt,money,esc,cents,sum,positive,pct,norm,dateLabel,shiftDay,levels,classification,latestEvaluations,dailyCalc,dailyText,parseEvaluations,reportRows} from './core.mjs';
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const m={user:null,seed:null,data:null,version:null,tab:'panel',day:today,month:today.slice(0,7),manager:'',period:'Antes das 18h',mode:'manual',category:'Todas',search:'',records:[],offset:0,notices:[],features:[],users:[],people:[],audit:[],dirty:false,pending:[],pendingType:null,navOpen:false,evalDrafts:new Set()};
const $=id=>document.getElementById(id),dev=()=>m.user?.roles?.includes('developer'),priv=()=>dev()||m.user?.roles?.includes('supervisor');
const nav=[['panel','◫','Painel da equipe'],['daily','◷','Meta do dia anterior'],['monthly','◎','Metas do mês'],['evaluations','▤','Avaliações'],['chairs','▥','Campanha de cadeiras'],['campaign2','↗','Campanhas 2'],['merit','◇','Mérito'],['sheets','▦','Abas da planilha'],['notices','♧','Notificações']];
const title=()=>nav.find(n=>n[0]===m.tab)?.[2]||m.seed?.sheetCatalog.find(s=>s.id===m.tab)?.title||({admin:'Administração',development:'Desenvolvimento',account:'Minha conta'}[m.tab])||'Gestão Equipe Amanda';
const button=(action,label,attrs='',primary=false)=>{const match=attrs.match(/class="([^"]*)"/),classes=[primary?'primary':'',match?.[1]||''].filter(Boolean).join(' ');return `<button data-action="${action}" class="${classes}" ${attrs.replace(/class="[^"]*"/,'')}>${label}</button>`};
const personOptions=(value,all=false)=>`${all?'<option value="">Toda a equipe</option>':''}${(priv()?managers:[m.user?.manager]).filter(Boolean).map(name=>`<option value="${esc(name)}" ${name===value?'selected':''}>${esc(names[name]||name)}</option>`).join('')}`;
const field=(name,label,type,value='',step='any')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?`min="0" step="${step}"`:''} required></label>`;
const table=(headers,rows)=>`<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(c=>`<td>${c??''}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const card=(label,value,note='')=>`<div class="card"><small>${label}</small><strong>${value}</strong><em>${note}</em></div>`;
const progress=(actual,target)=>`<progress max="100" value="${target?Math.max(0,Math.min(100,actual/target*100)):0}" aria-label="Avanço da meta"></progress>`;
const pill=(text,kind='')=>`<span class="badge ${kind}">${esc(text)}</span>`;
const statusLabel=s=>({pending:'Aguardando aprovação',approved:'Aprovado',blocked:'Bloqueado',rejected:'Recusado',new:'Novo',in_progress:'Em desenvolvimento',done:'Concluído'}[s]||s);
const rolesLabel=u=>u.roles.map(r=>({manager:'Gerente',supervisor:'Supervisora',developer:'Desenvolvedor'}[r]||r)).join(' • ');
function toast(text){$('toast').textContent=text;setTimeout(()=>{$('toast').textContent=''},5000)}
function errorMessage(error){if($('dialog').open&&$('dialog-error'))$('dialog-error').textContent=error.message;else if($('auth-error'))$('auth-error').textContent=error.message;else toast(error.message)}
async function api(path,method='GET',body,headers={}){const r=await fetch(path,{method,credentials:'same-origin',headers:{...(body!==undefined?{'Content-Type':'application/json'}:{}),...headers},...(body!==undefined?{body:JSON.stringify(body)}:{})});let data;try{data=await r.json()}catch{throw Error('Resposta inválida. Tente novamente.')}if(!r.ok){if(r.status===401&&m.user){clearPrivateState();renderAuth()}throw Object.assign(Error(data.error||'Não foi possível concluir a operação.'),{status:r.status})}let version=r.headers.get('X-State-Version');if(version)m.version=version;return data}
function modal(heading,content){const d=$('dialog');d.innerHTML=`<div class="dialoghead"><h2>${esc(heading)}</h2>${button('close','✕','aria-label="Fechar"')}</div><div id="dialog-error" class="error" role="alert"></div>${content}`;if(!d.open)d.showModal();d.querySelector('input:not([type=hidden]),select,textarea')?.focus()}
function num(form,name,integer=false){const value=form.elements.namedItem(name)?.value;const n=Number(value);if(value===''||!Number.isFinite(n)||n<0||(integer&&!Number.isInteger(n)))throw Error('Preencha as quantidades com valores válidos.');return n}
function managerValue(){return m.manager||m.user.manager||(priv()?managers[0]:'')}
function units(){return m.data.units.filter(u=>!m.manager||u.manager===m.manager)}
function datedUnits(){return units().map(u=>{const history=m.data.chairs.filter(r=>r.id===u.id&&r.date.startsWith(m.month)&&r.date<=m.day).sort((a,b)=>b.date.localeCompare(a.date));return {...u,...(history[0]||{}),undated:!history[0]}})}
function evalRows(day=true){const ids=new Set(units().map(u=>u.id));return latestEvaluations(m.data.evals.filter(r=>ids.has(r.id)&&(day?r.date===m.day:r.date.startsWith(m.month))))}
async function load(){const [seed,data,notices]=await Promise.all([api('/api/seed'),api('/api/state'),api('/api/notifications')]);m.seed=seed;m.data=data;m.notices=notices;if(!m.manager&&m.user.manager)m.manager=m.user.manager;render();}
async function saveData(next){await api('/api/state','PUT',next,{'If-Match':m.version});m.dirty=false;m.evalDrafts.clear();await load();toast('Lançamento salvo.');}
async function go(tab){if(m.dirty&&!confirm('Há valores não salvos. Deseja sair desta aba?'))return;m.dirty=false;m.evalDrafts.clear();m.navOpen=false;m.tab=tab;m.offset=0;m.search='';if(tab.startsWith('sheet-')){m.records=[];if(priv())m.manager=''};render();if(tab.startsWith('sheet-'))await loadSheet();if(tab==='admin')await loadAdmin();if(tab==='development')await loadFeatures();if(tab==='notices')await loadNotices();}
function clearPrivateState(){m.user=null;m.data=null;m.seed=null;m.version=null;m.records=[];m.users=[];m.audit=[];m.people=[];m.features=[];m.pending=[];m.notices=[];m.dirty=false;m.evalDrafts.clear();m.navOpen=false;m.manager='';$('dialog').close();$('dialog').replaceChildren()}
function renderAuth(mode='login'){m.user=null;$('app').innerHTML=`<div class="auth"><section class="auth-intro"><div class="auth-orbit" aria-hidden="true"></div><div class="brand">AMANDA<span>.</span></div><span class="eyebrow">GESTÃO DA EQUIPE</span><h1>Uma equipe. <br>Metas claras. <br>Resultados juntos.</h1><p>Todos os controles da sua carteira, organizados para você cuidar do que importa.</p><div class="auth-features"><span>01 <b>Registre o dia</b></span><span>02 <b>Acompanhe suas metas</b></span><span>03 <b>Evolua com a equipe</b></span></div></section><section class="auth-form"><div class="auth-card"><span class="eyebrow">SEU ESPAÇO DE TRABALHO</span><h2>${mode==='login'?'Bem-vindo de volta.':'Solicite seu acesso.'}</h2><p>${mode==='login'?'Entre com o usuário aprovado pelo desenvolvimento.':'O desenvolvedor analisará seu pedido e atribuirá seu perfil e sua carteira.'}</p><p id="auth-error" class="error" role="alert"></p><form data-form="${mode==='login'?'login':'signup'}">${mode==='login'?'':field('name','Nome completo','text')}<label>Usuário<input name="username" autocomplete="username" autocapitalize="none" spellcheck="false" minlength="3" maxlength="40" required></label><label>Senha<span class="password-field"><input id="auth-password" name="password" type="password" autocomplete="${mode==='login'?'current-password':'new-password'}" minlength="${mode==='login'?'1':'8'}" maxlength="128" required>${button('toggle-password','Mostrar','type="button" aria-controls="auth-password" aria-pressed="false"')}</span></label>${mode==='login'?'':`<label>Perfil solicitado<select name="role"><option value="manager">Gerente</option><option value="supervisor">Supervisora</option></select></label><label>Carteira solicitada<select name="manager"><option value="">Supervisão / definir na aprovação</option>${managers.map(n=>`<option value="${esc(n)}">${esc(names[n])}</option>`).join('')}</select></label><p class="muted">Use no mínimo 8 caracteres. Sua senha não será mostrada ao desenvolvedor.</p>`}<button class="primary" type="submit">${mode==='login'?'Entrar no sistema':'Enviar solicitação'}</button></form><div class="auth-links">${button(mode==='login'?'show-signup':'show-login',mode==='login'?'Primeiro acesso? Solicitar aprovação':'Já tenho acesso. Entrar','class="linkbutton"')}</div><p class="auth-footnote">Acesso pessoal • Aprovação pela administração</p></div></section></div>`}
function render(){if(!m.user||!m.data)return;const unread=m.notices.filter(n=>!n.read).length;const navItem=([id,icon,label])=>`<button data-action="navigate" data-tab="${id}" class="${m.tab===id?'active':''}" ${m.tab===id?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span><span>${label}</span>${id==='notices'&&unread?'<span class="nav-count">'+unread+'</span>':''}</button>`;$('app').innerHTML=`<a class="skip-link" href="#view">Ir para o conteúdo</a><div class="shell ${m.navOpen?'nav-open':''}"><button class="nav-backdrop" data-action="toggle-menu" aria-label="Fechar menu"></button><aside id="sidebar"><div class="brand-lockup"><img src="/icon.svg" alt="" width="40" height="40"><div><div class="brand">AMANDA<span>.</span></div><div class="brand-caption">GESTÃO DA EQUIPE</div></div></div><button class="nav-search" data-action="command-search"><span>⌕ Encontrar uma aba</span><kbd>Ctrl K</kbd></button><div class="account"><span class="avatar">${esc(m.user.name.split(' ').slice(0,2).map(n=>n[0]).join(''))}</span><div><strong>${esc(m.user.name)}</strong><small>${esc(names[m.user.manager]||'Supervisão')}</small><span class="account-role">${esc(rolesLabel(m.user))}</span>${m.user.is_pro?pill('PRO'):''}${dev()?pill('DEV'):''}</div></div><nav aria-label="Menu principal"><div class="nav-group">ACOMPANHAMENTO</div>${nav.slice(0,3).map(navItem).join('')}<div class="nav-group">LANÇAMENTOS E CAMPANHAS</div>${nav.slice(3,7).map(navItem).join('')}<div class="nav-group">CONTROLES</div>${nav.slice(7).map(navItem).join('')}${priv()?`<div class="nav-group">GESTÃO DO SISTEMA</div>${navItem(['development','＋','Pedidos de melhoria'])}`:''}${dev()?navItem(['admin','⚙','Administração']):''}<div class="nav-group">MEU ACESSO</div>${navItem(['account','◉','Minha conta'])}${button('logout','<span class="nav-icon" aria-hidden="true">↪</span> Sair do sistema')}</nav><div class="foot"><span class="status-dot"></span> Ambiente da equipe<br><small>${m.seed.sheetCatalog.length} abas em um só lugar</small></div></aside><main class="main"><div class="mobile-toolbar">${button('toggle-menu','☰ Menu','aria-controls="sidebar" aria-expanded="'+m.navOpen+'"') }<strong>AMANDA.</strong>${button('command-search','⌕ Buscar')}</div><header><div><div class="breadcrumb">Gestão da equipe <span>/</span> ${esc(title())}</div><h1 id="page-title" tabindex="-1">${esc(title())}</h1><small>${m.tab==='panel'?'Acompanhe o resultado e o ritmo de toda a equipe.':priv()?'Escolha uma carteira para acompanhar ou lançar resultados.':'Sua carteira, seus lançamentos e seus resultados.'}</small></div><div class="actions">${priv()?button('request-feature','＋ Melhoria nesta aba','class="ghost"'):''}${button('refresh','↻ Atualizar','class="ghost"')}${button('navigate','Avisos'+(unread?' <span class="nav-count">'+unread+'</span>':''),'data-tab="notices"')}</div></header>${!['admin','development','notices','account','sheets'].includes(m.tab)?filters():''}<div id="view" tabindex="-1">${view()}</div><div id="save-status" class="save-status" role="status" ${m.dirty?'':'hidden'}><span>● Você tem alterações não salvas.</span>${m.tab==='evaluations'&&m.mode==='manual'?button('save-evaluations','Salvar avaliações','',true):'<span>Conclua o formulário para salvar.</span>'}</div><footer class="page-footer">Gestão Equipe Amanda <span>Seu próximo resultado começa por um lançamento.</span></footer></main></div>`;syncNavigation();}
function filters(){const monthOnly=['monthly','merit'].includes(m.tab);return `<section class="filters" aria-label="Filtros de acompanhamento"><span class="filter-label">PERÍODO</span><label>Mês de referência<input type="month" data-filter="month" value="${m.month}" required></label>${monthOnly?'':`<label>Dia de referência<input type="date" data-filter="day" value="${m.day}" required></label><div class="date-shortcuts">${button('date-today','Hoje',`class="small ${m.day===today?'selected':''}"`)}${button('date-yesterday','Ontem','class="small"')}</div>`}${priv()&&m.tab!=='panel'?`<label class="portfolio-filter">Carteira<select data-filter="manager">${personOptions(m.manager,true)}</select></label>`:`<div class="filter-scope"><span class="status-dot"></span>${m.tab==='panel'?'Visão de toda a equipe':esc(names[m.user.manager]||'Supervisão')}</div>`}</section>`}
function view(){switch(m.tab){case'panel':return panelView();case'monthly':return monthlyView();case'daily':return dailyView();case'evaluations':return evaluationsView();case'chairs':return chairsView();case'campaign2':return campaignView();case'merit':return meritView();case'sheets':return catalogView();case'admin':return adminView();case'development':return developmentView();case'notices':return noticesView();case'account':return accountView();default:return sheetView()}}
function monthly(manager,global=false){const rows=global?m.data.overview.goals:m.data.goals,find=metric=>rows.find(r=>r.unit==='manager:'+manager&&r.period==='mes'&&r.date===m.month&&r.metric===metric);const cg=find('Clínico geral'),o=find('Pastas de ortodontia');return {manager,target:cg?.target||0,actual:cg?.actual||0,orthoTarget:o?.target||0,orthoActual:o?.actual||0,exists:!!cg}}
function panelView(){const figures=managers.map(n=>monthly(n,true)),daily=m.data.overview.daily.filter(r=>r.today===m.day),evals=m.data.overview.evaluations.filter(r=>r.date===m.day);return `${myDayTasks()}<div class="welcome"><div><span class="eyebrow">OLÁ, ${esc(m.user.name.split(' ')[0])}</span><h2>Uma visão clara do ritmo da equipe.</h2><p>O painel é coletivo. Seus lançamentos ficam separados nas demais abas.</p></div><div class="actions">${button('navigate','+ Lançar avaliações','data-tab="evaluations"',true)}${button('daily-form','Fechar dia anterior')}</div></div><div class="cards">${card('Clínico geral • realizado',money(sum(figures,'actual')),pct(sum(figures,'actual'),sum(figures,'target'))+' da meta mensal')}${card('Meta do mês • equipe',money(sum(figures,'target')),'Faltam '+money(positive(sum(figures,'target')-sum(figures,'actual'))))}${card('Ortodontia • pastas',fmt(sum(figures,'orthoActual'))+' / '+fmt(sum(figures,'orthoTarget')),'Acumulado mensal lançado')}${card('Avaliações • '+dateLabel(m.day),fmt(sum(evals,'total')),fmt(sum(evals,'attended'))+' atendidas')}</div><div class="grid"><section class="panel"><div class="spread"><h2>Metas mensais por gerente</h2>${button('navigate','Minhas metas →','data-tab="monthly"')}</div>${figures.map(r=>`<div class="manager-row"><div class="title-row"><span class="initials">${esc(r.manager.split(' ').slice(0,2).map(s=>s[0]).join(''))}</span><div><b>${esc(names[r.manager])}</b><div class="muted">Orto: ${fmt(r.orthoActual)} / ${fmt(r.orthoTarget)} pastas</div></div><b>${pct(r.actual,r.target)}</b></div>${progress(r.actual,r.target)}<div class="spread"><span>${money(r.actual)} <small>de ${money(r.target)}</small></span><small>Falta ${money(positive(r.target-r.actual))}</small></div></div>`).join('')}</section><section class="panel"><h2>O dia da equipe</h2>${table(['Gerente','Avaliações','Atendidas','Fechamento'],managers.map(n=>{const e=evals.find(r=>r.manager===n),d=daily.find(r=>r.manager===n);return [esc(names[n]),fmt(e?.total),fmt(e?.attended),d?pill('Lançado','success'):pill('Pendente','warn')]}))}<h2>Resultado do dia anterior</h2><div class="cards">${card('Meta CG',money(sum(daily,'cgTarget')))}${card('Efetivado',money(sum(daily,'cgActual')))}</div><p class="muted">${daily.length} de 6 gerentes lançaram o fechamento de ${dateLabel(shiftDay(m.day,-1))}.</p>${button('navigate','Abrir acompanhamento →','data-tab="daily"')}</section></div><div class="quick">${button('navigate','<strong>◇ Mérito</strong><small>Minha base, receita e objetivos</small>','data-tab="merit"')}${button('navigate','<strong>↗ Campanhas 2</strong><small>Quem está perto de subir de classificação</small>','data-tab="campaign2"')}${button('navigate','<strong>▦ Abas da planilha</strong><small>Os controles organizados por assunto</small>','data-tab="sheets"')}</div><p class="source">As metas iniciais de outubro/2026 vêm do relatório enviado. Resultados mensais são acumulados lançados, sem somar novamente os retratos do dia.</p>`}
function monthlyView(){const people=priv()?(m.manager?[m.manager]:managers):[m.user.manager],rows=people.map(n=>monthly(n));return `<div class="spread"><h2>Metas gerais do mês • ${m.month}</h2>${button('monthly-form','+ Lançar meta e resultado','',true)}</div><div class="cards">${card('Meta clínico geral',money(sum(rows,'target')))}${card('Valor efetivado',money(sum(rows,'actual')),'Falta '+money(positive(sum(rows,'target')-sum(rows,'actual'))))}${card('Meta ortodontia',fmt(sum(rows,'orthoTarget')))}${card('Pastas realizadas',fmt(sum(rows,'orthoActual')))}</div><section class="panel">${table(['Gerente','Meta CG','Efetivado','Falta CG','Avanço','Meta orto','Pastas','Faltam pastas','Ações'],rows.map(r=>[esc(names[r.manager]),money(r.target),money(r.actual),money(positive(r.target-r.actual)),pct(r.actual,r.target),r.orthoTarget,r.orthoActual,Math.max(0,r.orthoTarget-r.orthoActual),button('monthly-form','Atualizar',`data-manager="${esc(r.manager)}"`)]))}<p class="muted">Informe o acumulado do mês. Salvar substitui os valores anteriores do mesmo gerente e mês.</p></section>`}
function dailyView(){const rows=m.data.daily.filter(r=>r.today===m.day&&(!m.manager||r.manager===m.manager));return `<div class="spread"><div><h2>Resultado de ${dateLabel(shiftDay(m.day,-1))}</h2><p>Fechamento de ontem e planejamento de ${dateLabel(m.day)}.</p></div>${button('daily-form','+ Lançar fechamento','',true)}</div><div class="cards">${card('Meta de ontem',money(sum(rows,'cgTarget')))}${card('Efetivou ontem',money(sum(rows,'cgActual')))}${card('Pastas ontem',fmt(sum(rows,'orthoActual')),'Meta '+fmt(sum(rows,'orthoTarget')))}${card('Meta CG de hoje',money(sum(rows,'todayCg')))}</div><section class="panel">${rows.length?table(['Gerente','Meta CG','Efetivado','Faltou','Meta orto','Pastas','Faltam pastas','Saldo orto','Meta hoje','Avaliações hoje','Objetivo','Ações'],rows.map(r=>{const c=dailyCalc(r);return [esc(names[r.manager]),money(r.cgTarget),money(r.cgActual),money(c.cgMissing),r.orthoTarget,r.orthoActual,c.orthoMissing,c.orthoBalance,money(r.todayCg),r.evalTotal,r.evalRequired,button('daily-form','Editar',`data-manager="${esc(r.manager)}"`)+' '+button('daily-text','Texto',`data-manager="${esc(r.manager)}"`)]})):'<div class="empty">Ainda não há fechamento lançado nesta carteira e data.</div>'}<p class="muted">A falta tem mínimo zero. O saldo da ortodontia é realizado menos meta: 4 para uma meta de 12 gera falta de 8 e saldo −8.</p></section>`}
function evaluationsView(){const rows=evalRows(m.mode!=='month'),people=priv()?(m.manager?[m.manager]:managers):[m.user.manager];return `<div class="spread"><div><h2>Avaliações • clínica por clínica</h2><p>Escolha sua carteira, preencha as linhas e salve. O total é automático.</p></div>${button('paste-evaluations','Colar relatório')}</div><div class="chips">${[['manual','Lançamento manual'],['day','Consolidado do dia'],['month','Consolidado do mês']].map(([id,label])=>button('evaluation-mode',label,`data-mode="${id}" class="${m.mode===id?'active':''}"`)).join('')}</div>${m.mode==='manual'?manualEvaluations():`<div class="cards">${card('Total avaliações',fmt(sum(rows,'total')))}${card('Atendidas',fmt(sum(rows,'attended')))}${card('Canceladas',fmt(sum(rows,'cancelled')))}${card('Faltosos',fmt(sum(rows,'absent')))}</div><section class="panel"><h2>Quantidade total por gerente</h2>${table(['Gerente','Atendidas','Canceladas','Faltosos','Agendadas no dia','Total'],people.map(manager=>{const ids=new Set(m.data.units.filter(u=>u.manager===manager).map(u=>u.id)),a=rows.filter(r=>ids.has(r.id));return [esc(names[manager]),sum(a,'attended'),sum(a,'cancelled'),sum(a,'absent'),sum(a,'scheduled'),'<b>'+fmt(sum(a,'total'))+'</b>']}))}${table(['Dia','Retrato','Clínica','Atendidas','Canceladas','Faltosos','Agendadas','Total'],rows.map(r=>[dateLabel(r.date),esc(r.period),esc(m.data.units.find(u=>u.id===r.id)?.name||r.id),r.attended,r.cancelled,r.absent,r.scheduled,r.total]))}</section>`}`}
function manualEvaluations(){const owner=managerValue(),a=m.data.units.filter(u=>u.manager===owner).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));return `<section class="panel"><div class="spread"><div><span class="eyebrow">${esc(names[owner])}</span><h2>${dateLabel(m.day)} • ${a.length} clínicas</h2></div><div class="actions"><label>Retrato<select data-filter="period"><option ${m.period==='Antes das 18h'?'selected':''}>Antes das 18h</option><option ${m.period==='Depois das 18h'?'selected':''}>Depois das 18h</option></select></label>${button('save-evaluations','Salvar linhas marcadas','',true)}</div></div>${priv()&&!m.manager?'<p class="warning">Selecione uma carteira no filtro. O formulário abaixo está aberto para '+esc(names[owner])+'.</p>':''}<div class="clinic-toolbar"><label>Encontrar clínica<input id="clinic-search" type="search" placeholder="Nome ou código da clínica…" autocomplete="off"></label><span id="clinic-count" class="muted">${a.length} clínicas na carteira</span><span id="eval-draft-count" class="draft-count">Nenhuma alteração pendente</span></div>${table(['Lançar','Clínica','Atendidas','Canceladas','Faltosos','Agendadas no dia','Total','Salvar'],a.map(u=>{const r=m.data.evals.find(r=>r.id===u.id&&r.date===m.day&&r.period===m.period);return [`<input type="checkbox" data-eval-select="${esc(u.id)}" aria-label="Lançar ${esc(u.name)}" ${r?'checked':''}>`,`${esc(u.name)}<div class="muted">#${esc(u.id)} ${r?'• Já lançado':''}</div>`,...['attended','cancelled','absent','scheduled'].map(k=>`<input type="number" min="0" step="1" class="number-input" data-eval-field="${k}" data-clinic="${esc(u.id)}" aria-label="${k} ${esc(u.name)}" value="${r?r[k]:''}" placeholder="0">`),`<strong data-eval-total="${esc(u.id)}">${r?r.total:'—'}</strong>`,button('save-evaluation-one','Salvar',`data-clinic="${esc(u.id)}"`)]}))}<div class="spread"><p class="muted">Total = atendidas + canceladas + faltosos. Agendadas no dia fica separado.<br>Linhas em branco e desmarcadas não são registradas como zero.</p>${button('save-evaluations','Salvar linhas marcadas','',true)}</div></section>`}
function chairsView(){const a=datedUnits();return `<div class="spread"><div><h2>Campanha das cadeiras</h2><p>Atualize por relatório ou lance o acumulado de uma clínica.</p></div><div class="actions">${button('chairs-form','+ Lançar por clínica')}${button('chairs-import','↥ Importar XLSX / CSV','',true)}</div></div><div class="cards">${card('Efetivações',fmt(sum(a,'actual')))}${card('Meta • 40 por cadeira',fmt(sum(a,'target')))}${card('Cadeiras',fmt(sum(a,'chairs')))}${card('Avanço da meta',pct(sum(a,'actual'),sum(a,'target')))}</div><section class="panel">${table(['Clínica','Gerente','Referência','Cadeiras','Efetivações','Indicador / cadeira','Meta mensal','Ação'],a.map(u=>[esc(u.name),esc(names[u.manager]),u.undated?'Base sem data':dateLabel(u.date),u.chairs,u.actual,classification(u.actual,u.chairs).indicator,u.target,button('chairs-form','Atualizar',`data-clinic="${esc(u.id)}"`)]))}<p class="muted">Retratos acumulados do mesmo mês não são somados entre si. A comparação de classificação é atualizada na aba Campanhas 2.</p></section>`}
function campaignView(){const all=datedUnits().map(u=>{const c=classification(u.actual,u.chairs),history=m.data.chairs.filter(r=>r.id===u.id&&r.date.startsWith(m.month)&&r.date<(u.date||m.day)).sort((a,b)=>b.date.localeCompare(a.date)),p=history[0]||m.data.units.find(x=>x.id===u.id),previous=classification(p.actual,p.chairs);return {...u,c,previous,advanced:!u.undated&&c.index>previous.index}}).sort((a,b)=>(a.c.missing??Infinity)-(b.c.missing??Infinity));return `<div class="cards">${card('Avançaram no último retrato',all.filter(r=>r.advanced).length)}${card('Até 10 efetivações para subir',all.filter(r=>r.c.next&&r.c.missing<=10).length)}${card('Ouro',all.filter(r=>r.c.index===4).length)}${card('Unidades acompanhadas',all.length)}</div><section class="panel"><div class="spread"><div><h2>Prioridades para mudar de classificação</h2><p>As mais próximas aparecem primeiro.</p></div>${button('chairs-import','Atualizar relatório','',true)}</div>${table(['Clínica','Gerente','Mês passado','Antes da atualização','Atual','Próximo nível','Efetivações','Faltam para subir'],all.map(r=>[esc(r.name),esc(names[r.manager]),esc(m.seed.campaignMeta[r.id]?.month===m.month?m.seed.campaignMeta[r.id].lastMonth:'Não informado'),pill(r.previous.label),pill(r.c.label)+(r.advanced?' '+pill('↑ Avançou','success'):''),r.c.next?pill(r.c.next):'Manter Ouro',r.actual,r.c.next?'<b>'+fmt(r.c.missing)+'</b>':'Alcançado']))}<p class="muted">Como no relatório enviado, o indicador por cadeira é arredondado para cima. Faixas: abaixo de 10, 10–19, 20–29, 30–39 e 40 ou mais. A validação oficial é da franqueadora.</p></section>`}
function meritView(){const people=priv()?(m.manager?[m.manager]:managers):[m.user.manager];return `<div class="spread"><div><h2>Mérito por gerente</h2><p>As bases da planilha, com a receita recalculada a partir das clínicas.</p></div></div>${people.map(manager=>{const rows=m.data.merit.filter(r=>r.manager===manager&&r.month===m.month),t=m.data.meritTargets.find(r=>r.manager===manager&&r.month===m.month),unitBase=sum(rows,'base'),base=t?.sourceBase??unitBase,actual=sum(rows,'revenue'),gain1=base+(t?.gain1Offset??20000),gain2=base+(t?.gain2Offset??40000);return `<section class="panel"><div class="spread"><h2>${esc(names[manager])}</h2>${button('merit-targets','Objetivos',`data-manager="${esc(manager)}"`)}</div>${rows.length?`${Math.abs(base-unitBase)>.01?'<p class="warning">A base consolidada da fonte difere da soma das clínicas. Os objetivos preservam a base consolidada; confira em Objetivos.</p>':''}<div class="cards">${card('Receita atual',money(actual),pct(actual,base)+' da base')}${card('Base para igualar',money(base),'Falta '+money(positive(base-actual)))}${card('Ganhar 1',money(gain1),'Falta '+money(positive(gain1-actual)))}${card('Ganhar 2',money(gain2),'Falta '+money(positive(gain2-actual)))}</div>${table(['Clínica','Referência','Bônus','Pagas','Pastas','Base','Receita','Falta igualar','% base','Maior caixa','Falta maior caixa','Dias','Necessário / dia','Ação'],rows.map(r=>[esc(r.name),dateLabel(r.date),r.bonus,r.paid,r.paid+r.bonus,money(r.base),money(r.revenue),money(positive(r.base-r.revenue)),pct(r.revenue,r.base),money(r.recordCash),money(positive(r.recordCash-r.revenue)),r.days,r.days?money(positive(r.base-r.revenue)/r.days):'—',button('merit-form','Atualizar',`data-id="${esc(r.id)}" data-manager="${esc(manager)}"`)]))}`:`<div class="empty">Sem mérito neste mês. ${button('merit-copy','Criar com as bases da planilha',`data-manager="${esc(manager)}"`)}</div>`}</section>`}).join('')}<p class="source">Bases importadas de outubro/2026 sem data de atualização indicada. As faixas Ganhar 1 e Ganhar 2 preservam os ajustes da fonte, sem representar confirmação de premiação.</p>`}
function catalogView(){const sheets=m.seed.sheetCatalog.filter(s=>(m.category==='Todas'||s.category===m.category)&&(!m.search||norm(s.title+' '+s.category).includes(norm(m.search))));return `<div class="welcome"><div><h2>A lógica da sua planilha. Mais organizada.</h2><p>Abra uma aba para acompanhar seus controles. A supervisão pode solicitar melhorias pelo botão ＋.</p></div>${pill(m.seed.sheetCatalog.length+' abas')}</div><form data-form="catalog-search" class="inline-fields"><label>Encontrar uma aba<input name="query" type="search" value="${esc(m.search)}" placeholder="Mérito, caixa, agenda, intervenções…"></label><button type="submit">Pesquisar</button></form><div class="chips">${['Todas',...new Set(m.seed.sheetCatalog.map(s=>s.category))].map(c=>button('category',esc(c),`data-category="${esc(c)}" class="${c===m.category?'active':''}"`)).join('')}</div><div class="catalog">${sheets.map(s=>`<button data-action="open-sheet" data-sheet="${s.id}"><span class="eyebrow">${esc(s.category)}</span><strong>${esc(s.title)}</strong><small>${s.view?'Controle integrado ao sistema':'Registros e controles da aba'}</small></button>`).join('')}</div>`}
function sheetView(){const sheet=m.seed.sheetCatalog.find(s=>s.id===m.tab);if(!sheet)return '<div class="empty">Aba não encontrada.</div>';let rows=m.records.filter(r=>!m.search||norm(Object.values(r.data).join(' ')).includes(norm(m.search)));const columns=sheet.columns.length?sheet.columns:[{key:'A',label:'Descrição'},{key:'B',label:'Resultado'},{key:'C',label:'Observações'}];return `<section class="panel"><div class="spread"><div><span class="eyebrow">${esc(sheet.category)} • ABA DA PLANILHA</span><h2>${esc(sheet.title)}</h2></div><div class="actions">${button('sheet-record','+ Novo registro','',true)}${m.user.is_pro||priv()?button('export-sheet','Exportar CSV'):''}</div></div><p class="muted">${priv()?'Registros sem responsável confirmado ficam disponíveis apenas para supervisão e desenvolvimento.':'Somente seus registros são disponibilizados pelo servidor.'} Colunas e valores importados mantêm a referência da planilha. O histórico fica restrito à supervisão até que o responsável seja confirmado ao editar o registro.</p><form data-form="sheet-search" class="inline-fields"><label>Buscar nas linhas desta página<input name="query" type="search" value="${esc(m.search)}"></label><button>Buscar</button></form>${rows.length?table(['Responsável',...columns.map(c=>esc(c.label)), 'Ações'],rows.map(r=>[esc(names[r.owner_manager]||'Supervisão'),...columns.map(c=>`<span class="wrapcell">${esc(r.data[c.key]??'')}</span>`),button('sheet-record','Editar',`data-id="${r.id}"`)])):'<div class="empty">Nenhum registro disponível nesta seleção. Use Novo registro para iniciar este controle.</div>'}<div class="spread"><span class="muted">Página ${Math.floor(m.offset/200)+1} • ${m.records.length} registros carregados</span><div class="actions">${m.offset?button('sheet-prev','← Anterior'):''}${m.records.length===200?button('sheet-next','Próxima →'):''}</div></div></section>`}
function noticesView(){return `<div class="spread"><div><h2>Seus avisos</h2><p>Mensagens da supervisão e do desenvolvimento.</p></div><div class="actions">${button('enable-push','Ativar neste dispositivo','',true)}${priv()?button('notice-form','+ Enviar aviso'):''}</div></div><p class="hint">Para aparecer fora do sistema, ative as notificações neste dispositivo e permita no navegador. Por privacidade, o aviso externo não mostra o conteúdo da mensagem. Entre no sistema para ler. A entrega depende do suporte do dispositivo.</p><section class="panel">${m.notices.length?m.notices.map(n=>`<article class="notice"><div class="spread"><h3>${esc(n.title)} ${!n.read?pill('Novo','success'):''}</h3><small>${esc(new Date(n.created_at).toLocaleString('pt-BR'))}</small></div><p>${esc(n.body)}</p>${!n.read?button('read-notice','Marcar como lido',`data-id="${n.id}"`):''}</article>`).join(''):'<div class="empty">Nenhum aviso recebido.</div>'}</section>`}
function developmentView(){return `<div class="spread"><div><h2>Pedidos de desenvolvimento</h2><p>${dev()?'Solicitações da supervisão, organizadas por aba e andamento.':'Acompanhe as melhorias que você pediu para cada aba.'}</p></div>${priv()?button('request-feature','+ Nova solicitação','',true):''}</div>${m.features.map(r=>`<section class="panel"><div class="spread"><h2>${esc(r.title)}</h2>${pill(statusLabel(r.status))}</div><p class="muted">Aba: ${esc(m.seed.sheetCatalog.find(s=>s.id===r.sheet_id)?.title||nav.find(n=>n[0]===r.sheet_id)?.[2]||r.sheet_id)} • ${dateLabel(r.created_at.slice(0,10))}</p><p class="pre">${esc(r.description)}</p>${r.developer_note?'<div class="hint">'+esc(r.developer_note)+'</div>':''}${dev()?`<form data-form="feature-update" data-id="${r.id}"><div class="formgrid"><label>Andamento<select name="status">${['new','in_progress','done','rejected'].map(s=>`<option value="${s}" ${s===r.status?'selected':''}>${statusLabel(s)}</option>`).join('')}</select></label><label>Retorno do desenvolvimento<input name="note" value="${esc(r.developer_note)}" maxlength="3000"></label></div><button type="submit">Salvar andamento</button></form>`:''}</section>`).join('')||'<div class="empty">Nenhuma solicitação cadastrada.</div>'}`}
function adminView(){if(!dev())return '<div class="empty">Acesso restrito.</div>';const pending=m.users.filter(u=>u.status==='pending'),online=m.users.filter(u=>u.status==='approved'&&u.last_seen_at&&Date.now()-Date.parse(u.last_seen_at)<120000);return `<div class="cards">${card('Solicitações pendentes',pending.length)}${card('Acessos aprovados',m.users.filter(u=>u.status==='approved').length)}${card('Online nos últimos 2 minutos',online.length)}${card('Acessos bloqueados',m.users.filter(u=>u.status==='blocked').length)}</div><section class="panel"><div class="spread"><h2>Usuários, aprovação e permissões</h2>${button('reload-admin','Atualizar presença')}</div><p class="muted">A senha nunca é exibida. Aprove a solicitação, atribua a carteira e selecione os perfis. Bloquear invalida as sessões.</p>${table(['Usuário','Nome','Situação','Perfis','Carteira','Presença','Ações'],m.users.map(u=>[esc(u.username)+(u.is_pro?' '+pill('PRO'):''),esc(u.name),pill(statusLabel(u.status),u.status==='approved'?'success':u.status==='pending'?'warn':'bad'),esc(rolesLabel(u)||'Solicitado: '+u.requested_role),esc(names[u.manager||u.requested_manager]||'Definir na aprovação'),u.status==='approved'&&u.last_seen_at&&Date.now()-Date.parse(u.last_seen_at)<120000?'<span class="online">● Online</span>':u.last_seen_at?esc(new Date(u.last_seen_at).toLocaleString('pt-BR')):'Ainda não entrou',button('user-form',u.status==='pending'?'Analisar':'Gerenciar',`data-id="${u.id}"`)]))}</section><section class="panel"><h2>Atividade recente</h2>${table(['Quando','Ação','Usuário','Destino'],m.audit.map(a=>[esc(new Date(a.created_at).toLocaleString('pt-BR')),esc(a.action),esc(m.users.find(u=>u.id===a.actor_id)?.username||'—'),esc(a.target_id||'—')]))}</section>`}
function accountView(){return `<div class="account-grid"><section class="panel profile-panel"><span class="avatar large">${esc(m.user.name.split(' ').slice(0,2).map(n=>n[0]).join(''))}</span><h2>${esc(m.user.name)}</h2><p>@${esc(m.user.username)}</p><dl><dt>Meu perfil</dt><dd>${esc(rolesLabel(m.user))}</dd><dt>Minha carteira</dt><dd>${esc(names[m.user.manager]||'Supervisão')}</dd></dl>${button('password-form','Alterar minha senha','',true)}</section><div><section class="panel"><span class="eyebrow">PRIVACIDADE</span><h2>Seu acesso é pessoal.</h2><p>Seus dados são disponibilizados conforme seu perfil. Ao trocar a senha, todas as suas sessões são encerradas.</p><p class="hint">Use uma senha exclusiva e saia da conta ao usar um computador compartilhado.</p></section><section class="panel"><span class="eyebrow">AVISOS DA EQUIPE</span><h2>Notificações neste dispositivo</h2><p>Receba um lembrete quando chegar uma mensagem. O conteúdo completo aparece somente dentro do sistema, após entrar na sua conta.</p><div class="actions">${button('enable-push','Ativar notificações','',true)}${button('disable-push','Desativar')}</div></section></div></div>`}
function monthlyForm(manager=managerValue()){const r=monthly(manager);modal('Meta e resultado mensal',`<form data-form="monthly"><label>Gerente<select name="manager">${personOptions(manager)}</select></label><p>${m.month} • informe o acumulado do mês.</p><div class="formgrid">${field('target','Meta clínico geral • R$','number',r.target,'0.01')}${field('actual','Efetivado • R$','number',r.actual,'0.01')}${field('orthoTarget','Meta ortodontia','number',r.orthoTarget,'1')}${field('orthoActual','Pastas realizadas','number',r.orthoActual,'1')}</div><button class="primary">Salvar metas e resultados</button></form>`)}
function dailyForm(manager=managerValue()){const r=m.data.daily.find(r=>r.manager===manager&&r.today===m.day)||{cgTarget:0,cgActual:0,orthoTarget:0,orthoActual:0,todayCg:0,todayOrtho:0,evalTotal:0,evalRequired:0};modal('Fechamento do dia anterior',`<form data-form="daily"><label>Gerente<select name="manager">${personOptions(manager)}</select></label><p>Resultado de ${dateLabel(shiftDay(m.day,-1))} • planejamento de ${dateLabel(m.day)}</p><h3>Resultado de ontem</h3><div class="formgrid">${field('cgTarget','Meta CG • R$','number',r.cgTarget,'0.01')}${field('cgActual','Efetivado • R$','number',r.cgActual,'0.01')}${field('orthoTarget','Meta orto','number',r.orthoTarget,'1')}${field('orthoActual','Pastas realizadas','number',r.orthoActual,'1')}</div><h3>Objetivo de hoje</h3><div class="formgrid">${field('todayCg','Meta CG hoje • R$','number',r.todayCg,'0.01')}${field('todayOrtho','Meta orto hoje','number',r.todayOrtho,'1')}${field('evalTotal','Avaliações disponíveis hoje','number',r.evalTotal,'1')}${field('evalRequired','Avaliações que preciso efetivar','number',r.evalRequired,'1')}</div><button class="primary">Salvar fechamento</button></form>`)}
function chairsForm(id){const a=units(),u=a.find(u=>u.id===id)||a[0];if(!u)return toast('Nenhuma clínica atribuída.');const r=datedUnits().find(r=>r.id===u.id)||u;modal('Lançar campanha por clínica',`<form data-form="chairs"><label>Clínica<select name="id">${a.map(x=>`<option value="${esc(x.id)}" ${x.id===u.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><p>Referência: ${dateLabel(m.day)} • acumulado do mês</p><div class="formgrid">${field('chairs','Cadeiras válidas','number',r.chairs,'1')}${field('actual','Efetivações acumuladas','number',r.actual,'1')}</div><p class="muted">A meta total é calculada em 40 efetivações por cadeira.</p><button class="primary">Salvar retrato</button></form>`)}
function meritForm(id,manager){const r=m.data.merit.find(r=>r.id===id&&r.manager===manager&&r.month===m.month);if(!r)return;modal('Atualizar mérito',`<form data-form="merit" data-id="${esc(id)}" data-manager="${esc(manager)}"><p>${esc(r.name)} • base preservada ${money(r.base)}</p><div class="formgrid">${field('date','Referência','date',r.date||m.day)}${field('revenue','Receita atual • R$','number',r.revenue,'0.01')}${field('paid','Pastas pagas','number',r.paid,'1')}${field('bonus','Pastas bônus','number',r.bonus,'1')}${field('days','Dias úteis restantes','number',r.days,'1')}${field('recordCash','Maior caixa de referência','number',r.recordCash,'0.01')}</div><button class="primary">Salvar atualização</button></form>`)}
function meritTargetsForm(manager){const rows=m.data.merit.filter(r=>r.manager===manager&&r.month===m.month),t=m.data.meritTargets.find(r=>r.manager===manager&&r.month===m.month);modal('Objetivos de mérito',`<form data-form="merit-targets" data-manager="${esc(manager)}"><p>${esc(names[manager])} • ${m.month}</p><div class="formgrid">${field('sourceBase','Base consolidada do gerente','number',t?.sourceBase??sum(rows,'base'),'0.01')}${field('gain1Offset','Acréscimo para Ganhar 1','number',t?.gain1Offset??20000,'0.01')}${field('gain2Offset','Acréscimo para Ganhar 2','number',t?.gain2Offset??40000,'0.01')}</div><button class="primary">Salvar objetivos</button></form>`)}
function featureForm(){modal('Solicitar uma melhoria nesta aba',`<form data-form="feature"><p>Aba de referência: <b>${esc(title())}</b><br>Seu pedido irá para a fila do desenvolvimento.</p>${field('title','O que você precisa?','text')}<label>Descreva o controle, campos ou comportamento desejado<textarea name="description" maxlength="5000" required placeholder="Ex.: nesta aba preciso acompanhar…"></textarea></label><button class="primary">Enviar para o desenvolvimento</button></form>`)}
function userForm(id){const u=m.users.find(u=>u.id===id);if(!u)return;modal('Gerenciar acesso',`<form data-form="user" data-id="${u.id}"><p><b>${esc(u.name)}</b> • ${esc(u.username)}<br>Pedido: ${esc(u.requested_role)} • ${esc(names[u.requested_manager]||'sem carteira solicitada')}</p><div class="formgrid"><label>Situação<select name="status">${['pending','approved','blocked','rejected'].map(s=>`<option value="${s}" ${(u.status==='pending'?s==='approved':s===u.status)?'selected':''}>${statusLabel(s)}</option>`).join('')}</select></label><label>Carteira de gerente<select name="manager"><option value="">Sem carteira / supervisão</option>${managers.map(n=>`<option value="${esc(n)}" ${(u.manager||u.requested_manager)===n?'selected':''}>${esc(names[n])}</option>`).join('')}</select></label></div><h3>Perfis</h3><div class="row">${[['manager','Gerente'],['supervisor','Supervisora'],['developer','Desenvolvedor']].map(([role,label])=>`<label class="checklabel"><input type="checkbox" name="role-${role}" ${u.roles.includes(role)||(u.status==='pending'&&u.requested_role===role)?'checked':''}>${label}</label>`).join('')}<label class="checklabel"><input type="checkbox" name="is_pro" ${u.is_pro?'checked':''}>PRO</label></div><p class="warning">O perfil Desenvolvedor concede administração total. A supervisão acompanha e altera todas as carteiras. Gerentes acessam apenas a carteira atribuída.</p><button class="primary">Salvar aprovação e permissões</button></form>`)}
function sheetRecordForm(id){const sheet=m.seed.sheetCatalog.find(s=>s.id===m.tab),r=m.records.find(r=>r.id===id),columns=sheet.columns.length?sheet.columns:[{key:'A',label:'Descrição'},{key:'B',label:'Resultado'},{key:'C',label:'Observações'}];modal(r?'Editar controle':'Novo registro',`<form data-form="sheet-record" data-id="${r?.id||''}"><p>${esc(sheet.title)}</p>${r?.suggested_manager&&!r.owner_manager?'<p class="hint">Sugestão histórica a confirmar: '+esc(names[r.suggested_manager]||r.suggested_manager)+'. O acesso permanece restrito até você selecionar o responsável.</p>':''}${priv()?`<label>Responsável<select name="owner"><option value="">Somente supervisão / desenvolvimento</option>${managers.map(n=>`<option value="${esc(n)}" ${(r?r.owner_manager:managerValue())===n?'selected':''}>${esc(names[n])}</option>`).join('')}</select></label>`:''}<div class="formgrid">${columns.map(c=>`<label>${esc(c.label)}<input name="cell-${esc(c.key)}" value="${esc(r?.data[c.key]??'')}" maxlength="5000"></label>`).join('')}</div><button class="primary">Salvar registro</button></form>`)}
async function loadSheet(){m.records=await api('/api/sheets/'+m.tab+'?offset='+m.offset+(priv()&&m.manager?'&manager='+encodeURIComponent(m.manager):''));render()}
async function loadAdmin(){[m.users,m.audit]=await Promise.all([api('/api/admin/users'),api('/api/admin/audit')]);render()}
async function loadFeatures(){m.features=await api('/api/features');render()}
async function loadNotices(){m.notices=await api('/api/notifications');render()}
async function saveEvaluations(single){const drafts=single?[...m.evalDrafts].filter(id=>id!==single).map(id=>({id,values:Object.fromEntries(['attended','cancelled','absent','scheduled'].map(k=>[k,document.querySelector(`[data-eval-field="${k}"][data-clinic="${CSS.escape(id)}"]`)?.value??'']))})):[];const owner=managerValue(),a=m.data.units.filter(u=>u.manager===owner).filter(u=>single?u.id===single:document.querySelector(`[data-eval-select="${CSS.escape(u.id)}"]`)?.checked);if(!a.length)throw Error('Preencha ou marque pelo menos uma clínica.');const records=a.map(u=>{const value=k=>{const text=document.querySelector(`[data-eval-field="${k}"][data-clinic="${CSS.escape(u.id)}"]`).value;if(text==='')return 0;const n=Number(text);if(!Number.isInteger(n)||n<0)throw Error('Informe quantidades inteiras e positivas em '+u.name);return n};const attended=value('attended'),cancelled=value('cancelled'),absent=value('absent'),scheduled=value('scheduled');return {id:u.id,manager:u.manager,date:m.day,period:m.period,attended,cancelled,absent,scheduled,total:attended+cancelled+absent,source:'manual'}});const next=structuredClone(m.data);next.evals=next.evals.filter(e=>!records.some(r=>r.id===e.id&&r.date===e.date&&r.period===e.period)).concat(records);await saveData(next);for(const draft of drafts){for(const [k,v]of Object.entries(draft.values)){const input=document.querySelector(`[data-eval-field="${k}"][data-clinic="${CSS.escape(draft.id)}"]`);if(input)input.value=v}const checkbox=document.querySelector(`[data-eval-select="${CSS.escape(draft.id)}"]`);if(checkbox)checkbox.checked=true;const total=document.querySelector(`[data-eval-total="${CSS.escape(draft.id)}"]`);if(total)total.textContent=fmt(['attended','cancelled','absent'].reduce((s,k)=>s+(Number(draft.values[k])||0),0));m.evalDrafts.add(draft.id)}m.dirty=drafts.length>0;updateDraftStatus()}
function importPreview(){modal('Conferir antes de importar',`<p>${m.pending.length} registros válidos • referência ${dateLabel(m.day)}</p>${m.importIssues?.length?'<p class="warning">'+m.importIssues.map(esc).join('<br>')+'</p>':''}${table(['Unidade','Resultado'],m.pending.slice(0,100).map(r=>[esc(r.name||m.data.units.find(u=>u.id===r.id)?.name),m.pendingType==='evaluations'?r.total+' avaliações':r.actual+' efetivações']))}${m.pending.length?button('confirm-import','Confirmar e salvar registros','',true):''}`)}
async function readChairs(file){const rows=await reportRows(file),hi=rows.findIndex(r=>r.some(v=>norm(v)==='FRANQUIA')&&r.some(v=>norm(v)==='CADEIRAS'));if(hi<0)throw Error('Não encontrei as colunas do relatório Admin.');const h=rows[hi].map(norm),idx=k=>h.indexOf(k);for(const k of ['FRANQUIA','CADEIRAS','EFETIVACOES'])if(idx(k)<0)throw Error('Coluna ausente: '+k);let out=[],issues=[];const seen=new Set();for(const r of rows.slice(hi+1)){const name=String(r[idx('FRANQUIA')]||'');if(!name.trim())continue;const id=name.match(/\[F?\s*(\d+)\]/)?.[1]||m.data.units.find(u=>norm(u.name)===norm(name))?.id,u=m.data.units.find(u=>u.id===id);if(!u)continue;if(seen.has(id)){issues.push('Unidade repetida: '+id);continue}seen.add(id);const chairs=Number(r[idx('CADEIRAS')]),actual=Number(r[idx('EFETIVACOES')]);if(!(chairs>0)||!Number.isInteger(chairs)||!Number.isInteger(actual)||actual<0){issues.push('Valores inválidos: '+name);continue}out.push({id:u.id,name:u.name,manager:u.manager,supervisor:u.supervisor,chairs,actual,target:chairs*40})}m.pending=out;m.pendingType='chairs';m.importIssues=issues;importPreview()}
async function enablePush(){if(!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window))throw Error('Este navegador não oferece notificações em segundo plano.');const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('A permissão não foi concedida. Você pode continuar acompanhando os avisos no sistema.');const reg=await navigator.serviceWorker.register('/sw.js');await navigator.serviceWorker.ready;const {publicKey}=await api('/api/push/key');if(!publicKey)throw Error('Notificações ainda não configuradas.');const bytes=Uint8Array.from(atob(publicKey.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));let subscription=await reg.pushManager.getSubscription();subscription=subscription||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:bytes});await api('/api/push/subscribe','POST',subscription.toJSON());toast('Notificações ativadas neste dispositivo.')}
async function disablePush(){const reg=await navigator.serviceWorker?.getRegistration('/');const s=await reg?.pushManager.getSubscription();if(s){await api('/api/push/unsubscribe','POST',{endpoint:s.endpoint});await s.unsubscribe()}toast('Notificações desativadas neste dispositivo.')}
async function logout(){if(m.dirty&&!confirm('Há alterações não salvas. Deseja sair?'))return;let endpoint;try{const r=await navigator.serviceWorker?.getRegistration('/'),s=await r?.pushManager.getSubscription();for(const notice of await r?.getNotifications()||[])notice.close();if(s){endpoint=s.endpoint;await s.unsubscribe()}}catch{}try{await api('/api/auth/logout','POST',{endpoint})}finally{clearPrivateState();renderAuth()}}
