 'show-signup':()=>renderAuth('signup'),'show-login':()=>renderAuth(),'close':()=>{if($('dialog').querySelector('[data-form=feature-update]')&&m.dirty&&!confirm('Descartar alterações?'))return;$('dialog').close()},
 'navigate':async e=>{await go(e.dataset.tab);$('page-title')?.focus()},'refresh':async()=>{if(m.dirty&&!confirm('Descartar alterações não salvas e atualizar?'))return;m.dirty=false;m.evalDrafts.clear();await load();if(m.tab.startsWith('sheet-'))await loadSheet();if(m.tab==='admin')await loadAdmin();if(m.tab==='development')await loadFeatures();if(m.tab==='notices')await loadNotices()},'logout':logout,
