 'merit-copy':async e=>{const manager=e.dataset.manager,rows=m.seed.merit.filter(r=>r.manager===manager);if(m.data.merit.some(r=>r.manager===manager&&r.month===m.month))throw Error('O mérito deste mês já existe.');const next=structuredClone(m.data);next.merit.push(...rows.map(r=>({...r,month:m.month,date:null,revenue:0,paid:0,bonus:0,days:0})));await saveData(next)},
 'category':e=>{m.category=e.dataset.category;render()},'open-sheet':e=>{const s=m.seed.sheetCatalog.find(s=>s.id===e.dataset.sheet);return go(s.view||s.id)},'sheet-record':e=>sheetRecordForm(e.dataset.id),'sheet-next':async()=>{m.offset+=200;await loadSheet()},'sheet-prev':async()=>{m.offset=Math.max(0,m.offset-200);await loadSheet()},
